cd /workspace && python3 -c "
import sys; sys.path.insert(0,'/workspace/submission'); sys.path.insert(0,'/workspace/deps')
import zstandard as zstd, io
from classify_responses import complete_frames
from common import CaptureError
for wl in (17,27,28,31):
  try:
    p=zstd.ZstdCompressionParameters(window_log=wl)
    blob=zstd.ZstdCompressor(compression_params=p, write_content_size=False).compress(b'abc'*1000)
    fp=zstd.get_frame_parameters(blob)
    print('wl',wl,'declared window',fp.window_size)
    try: complete_frames(blob); print('   walk accepted')
    except CaptureError as e: print('   walk rejected:',e)
    try:
      d=zstd.ZstdDecompressor(max_window_size=128*1024**2).stream_reader(io.BytesIO(blob),read_across_frames=True).read()
      print('   lib accepted',len(d))
    except Exception as e: print('   lib rejected',type(e).__name__)
  except Exception as e: print(wl,'ERR',e)
"
